     * These Schur matrices depend only on RAM constants.
     * Precompute reusable products in RAM; CODE only multiplies them by runtime vectors.
     * ************************************************************************ */



    /* W_1_1 represents W[1,1]: (1.0/4.0)*R. */
    W_1_1 = (1.0/4.0)*R;
    /* W_2_2 represents W[2,2]: 1.0/(G8 + G9). */
    W_2_2 = 1.0/(G8 + G9);
    /* Gkr_shared_1 represents Gkr[N2,N1], Gkr[N2,N3]: -2.0/R. */
    Gkr_shared_1 = -2.0/R;
    /* Gkr_N4_N1 represents Gkr[N4,N1]: -G8. */
    Gkr_N4_N1 = -G8;
    /* Gkr_N4_N3 represents Gkr[N4,N3]: -G9. */
    Gkr_N4_N3 = -G9;
    set(&W_code, 0, 0, W_1_1);
    set(&W_code, 1, 1, W_2_2);
    set(&Gkr_code, 0, 0, Gkr_shared_1);
    set(&Gkr_code, 0, 1, Gkr_shared_1);
    set(&Gkr_code, 1, 0, Gkr_N4_N1);
    set(&Gkr_code, 1, 1, Gkr_N4_N3);
    matrix_mult(&tmp_W_Gkr_code, &W_code, &Gkr_code);

    matrix_register(&Vr_code);
    matrix_register(&Vk_code);
    matrix_register(&tmp_W_Gkr_code);
    matrix_register(&tmp_W_Gkr_Vr_code);

