    }



    /* Node injection currents follow the retained-node order of the reduced system. */
    InjN1 = 0.0;
    InjN4 = 0.0;

T1_T2:
    /* Internal-node voltage recovery after solved retained-node voltages are available. */
    set_CODE(&Vr_code, 0, 0, N1);
    set_CODE(&Vr_code, 1, 0, N4);
    /* Case-specific voltage recovery for Pack cases with different internal reductions. */
    switch (case_id) {
    case 0:
        /* Diagonal Gkk scalar CODE path: Vk[k] = -(Gkr[k,*] * Vr + Ihisk[k]) / Gkk[k,k]. */
        {
            double inv_gkk_diag[INTERNAL_NODES];
            for (int k = 0; k < internal_active; k++) {
                inv_gkk_diag[k] = 1.0 / get_CODE(&Gkk_code, k, k);
            }
            for (int k = 0; k < internal_active; k++) {
                double vk_sum = 0.0;
                for (int j = 0; j < RETAINED_NODES; j++) {
                    vk_sum += get_CODE(&Gkr_code, k, j) * get_CODE(&Vr_code, j, 0);
                }
                set_CODE(&Vk_code, k, 0, -vk_sum * inv_gkk_diag[k]);
            }
        }
        N2 = get_CODE(&Vk_code, 0, 0);
        break;
    case 1:
        /* This Pack case has no recovered internal nodes. */
        break;
    default:
        break;
    }

/* Multi-case C draft with forced scalar Schur expansion.
   Each init-time case is reduced to scalar final G/Ihis formulas;
   runtime Gkk/W MATRIX_ objects are intentionally not generated. */
enum { NR_SUPER = 2, NR_FINAL_MAX = 2, CASE_COUNT = 2 };

LOCAL_STATIC:
    double Gvar = 0.0;
    double R = 0.0;

RAM_PASS1:
    int err = 0;
    /* Case-specific scalar-expanded RAM G stamp. */
    switch (case_id) {
    case 0:
        g_mat_nods[0] = getNodeNum(comp, "N1");
        g_mat_nods[1] = getNodeNum(comp, "N2");
        for (int row = 0; row < 2; row++) {
            for (int col = 0; col < 2; col++) {
                g_mat_over[row][col] = 0.0;
            }
        }
        g_mat_over[0][0] = 1.0/R - 1.0/(pow(R, 2.0)*(Gvar + 1.0/R));
        g_mat_over[0][1] = -Gvar/(R*(Gvar + 1.0/R));
        g_mat_over[1][0] = -Gvar/(R*(Gvar + 1.0/R));
        g_mat_over[1][1] = -pow(Gvar, 2.0)/(Gvar + 1.0/R) + Gvar;
        setupGMatrix(2);
        break;
    case 1:
        g_mat_nods[0] = getNodeNum(comp, "N1");
        g_mat_nods[1] = getNodeNum(comp, "N2");
        for (int row = 0; row < 2; row++) {
            for (int col = 0; col < 2; col++) {
                g_mat_over[row][col] = 0.0;
            }
        }
        g_mat_over[0][0] = 1.0/R;
        g_mat_over[0][1] = -1.0/R;
        g_mat_over[1][0] = -1.0/R;
        g_mat_over[1][1] = 1.0/R;
        setupGMatrix(2);
        break;
    default:
        reportError_RW("network_node", STOP_IMMEDIATELY_CONDITION,
                       "Unknown force-scalar multi-case profile %d for component %s.", case_id, Name);
        break;
    }
    if (err > 0) {
        reportError_RW("network_node", STOP_IMMEDIATELY_CONDITION,
                       "RTDS force-scalar allocation failed for component %s.", Name);
    }

CODE:
BEGIN_T0:
    /* Node injection currents follow the scalar-expanded retained-node order. */
    switch (case_id) {
    case 0:
        InjN1 = 0.0;
        InjN4 = 0.0;
        break;
    case 1:
        InjN1 = 0.0;
        InjN4 = 0.0;
        break;
    default:
        break;
    }

T1_T2:
    /* Case-specific scalar-expanded internal-node voltage recovery. */
    switch (case_id) {
    case 0:
        N2 = (1.0/(R*(Gvar + 1.0/R)))*N1 + (Gvar/(Gvar + 1.0/R))*N4;
        break;
    case 1:
        /* This Pack case has no recovered internal nodes. */
        break;
    default:
        break;
    }
